const clock = new THREE.Clock();

// Cold, institutional background - pale gray with slight blue tint
scene.background = new THREE.Color(0xc5cbd3);
scene.fog = new THREE.FogExp2(0xc5cbd3, 0.035);

renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.02;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

// Multi-layered lighting for that dusty April atmosphere
const sunLight = new THREE.SpotLight(0xfff4e0, 1.8);
sunLight.position.set(-8, 6, 2);
sunLight.angle = Math.PI / 6;
sunLight.penumbra = 0.4;
sunLight.decay = 2;
sunLight.distance = 50;
sunLight.castShadow = true;
sunLight.shadow.mapSize.width = 2048;
sunLight.shadow.mapSize.height = 2048;
sunLight.shadow.bias = -0.0001;

const fillLight = new THREE.DirectionalLight(0x9cb3d6, 0.4);
fillLight.position.set(5, 2, 5);

const ambientLight = new THREE.AmbientLight(0x6b7585, 0.35);

// Telescreen glow - oppressive blue-white flicker
const telescreenLight = new THREE.PointLight(0x4a90e2, 0.8, 8);
telescreenLight.position.set(3, 2.5, -2);

scene.add(sunLight, fillLight, ambientLight, telescreenLight);

// Material library - utilitarian, worn, cold
const plasterMat = new THREE.MeshStandardMaterial({ 
  color: 0xb8bfc9, 
  roughness: 0.95, 
  metalness: 0.02 
});

const floorMat = new THREE.MeshStandardMaterial({ 
  color: 0x8a9199, 
  roughness: 0.9, 
  metalness: 0.05 
});

const woodMat = new THREE.MeshStandardMaterial({ 
  color: 0x5c5248, 
  roughness: 0.85,
  metalness: 0.1
});

const clothMat = new THREE.MeshStandardMaterial({ 
  color: 0x2e4057, 
  roughness: 1.0,
  metalness: 0.0,
  side: THREE.DoubleSide
});

const metalMat = new THREE.MeshStandardMaterial({
  color: 0x4a4a4a,
  roughness: 0.4,
  metalness: 0.8
});

// Generate Big Brother poster texture
function createPosterTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 1024;
  canvas.height = 1536;
  const ctx = canvas.getContext('2d');

  // Faded red background
  ctx.fillStyle = '#8b2635';
  ctx.fillRect(0, 0, 1024, 1536);

  // Grain/noise
  for(let i = 0; i < 50000; i++) {
    ctx.fillStyle = `rgba(0,0,0,${Math.random() * 0.1})`;
    ctx.fillRect(Math.random() * 1024, Math.random() * 1536, 2, 2);
  }

  // Big Brother face (simplified ominous features)
  ctx.fillStyle = '#1a1a1a';
  ctx.beginPath();
  ctx.arc(512, 600, 280, 0, Math.PI * 2);
  ctx.fill();

  // Eyes - intense stare
  ctx.fillStyle = '#000000';
  ctx.beginPath();
  ctx.ellipse(420, 550, 60, 40, 0, 0, Math.PI * 2);
  ctx.ellipse(604, 550, 60, 40, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(420, 550, 20, 0, Math.PI * 2);
  ctx.arc(604, 550, 20, 0, Math.PI * 2);
  ctx.fill();

  // Mustache
  ctx.fillStyle = '#0a0a0a';
  ctx.beginPath();
  ctx.rect(350, 680, 324, 80);
  ctx.fill();

  // Text
  ctx.fillStyle = '#f0f0f0';
  ctx.font = 'bold 80px Arial';
  ctx.textAlign = 'center';
  ctx.fillText('BIG BROTHER', 512, 1100);
  ctx.fillText('IS WATCHING YOU', 512, 1200);

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

const posterTexture = createPosterTexture();
const posterMat = new THREE.MeshBasicMaterial({ map: posterTexture });

// Room geometry
const roomGroup = new THREE.Group();
scene.add(roomGroup);

// Floor
const floor = new THREE.Mesh(
  new THREE.PlaneGeometry(12, 12),
  floorMat
);
floor.rotation.x = -Math.PI / 2;
floor.receiveShadow = true;
roomGroup.add(floor);

// Walls (back and left)
const backWall = new THREE.Mesh(
  new THREE.PlaneGeometry(12, 6),
  plasterMat
);
backWall.position.set(0, 3, -6);
backWall.receiveShadow = true;
roomGroup.add(backWall);

const leftWall = new THREE.Mesh(
  new THREE.PlaneGeometry(12, 6),
  plasterMat
);
leftWall.rotation.y = Math.PI / 2;
leftWall.position.set(-6, 3, 0);
leftWall.receiveShadow = true;
roomGroup.add(leftWall);

// Window frame
const windowGroup = new THREE.Group();
windowGroup.position.set(-6, 3, 0);
windowGroup.rotation.y = Math.PI / 2;

const frameMat = new THREE.MeshStandardMaterial({ color: 0x3a3a3a, roughness: 0.7 });
const frame = new THREE.Mesh(
  new THREE.BoxGeometry(4, 4, 0.2),
  frameMat
);
windowGroup.add(frame);

// Window glass - grimy, dusty
const glassGeo = new THREE.PlaneGeometry(3.6, 3.6);
const glassMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  metalness: 0,
  roughness: 0.2,
  transmission: 0.6,
  thickness: 0.1,
  opacity: 0.4,
  transparent: true,
  envMapIntensity: 1
});
const glass = new THREE.Mesh(glassGeo, glassMat);
glass.position.z = 0.11;
windowGroup.add(glass);

// Window bars/grime
const barGeo = new THREE.BoxGeometry(3.6, 0.05, 0.05);
const bar1 = new THREE.Mesh(barGeo, frameMat);
bar1.position.y = 1;
bar1.position.z = 0.15;
windowGroup.add(bar1);
const bar2 = new THREE.Mesh(barGeo, frameMat);
bar2.position.y = -1;
bar2.position.z = 0.15;
windowGroup.add(bar2);
const bar3 = new THREE.Mesh(new THREE.BoxGeometry(0.05, 3.6, 0.05), frameMat);
bar3.position.x = 0;
bar3.position.z = 0.15;
windowGroup.add(bar3);

roomGroup.add(windowGroup);

// Big Brother Poster - dominating the back wall
const posterGeo = new THREE.PlaneGeometry(3, 4.5);
const poster = new THREE.Mesh(posterGeo, posterMat);
poster.position.set(0, 3, -5.95);
poster.castShadow = true;
roomGroup.add(poster);

// Telescreen - mounted on right wall (visible from camera)
const telescreenGroup = new THREE.Group();
telescreenGroup.position.set(6, 3.5, 0);
telescreenGroup.rotation.y = -Math.PI / 2;

const tsFrame = new THREE.Mesh(
  new THREE.BoxGeometry(2.4, 1.8, 0.3),
  new THREE.MeshStandardMaterial({ color: 0x2a2a2a, roughness: 0.5, metalness: 0.6 })
);
telescreenGroup.add(tsFrame);

const tsScreenGeo = new THREE.PlaneGeometry(2.2, 1.6);
const tsScreenMat = new THREE.MeshBasicMaterial({ color: 0x4a90e2 });
const tsScreen = new THREE.Mesh(tsScreenGeo, tsScreenMat);
tsScreen.position.z = 0.16;
telescreenGroup.add(tsScreen);

// Speaker grill
const grill = new THREE.Mesh(
  new THREE.PlaneGeometry(2, 0.3),
  new THREE.MeshBasicMaterial({ color: 0x1a1a1a })
);
grill.position.set(0, -1.1, 0.16);
telescreenGroup.add(grill);

roomGroup.add(telescreenGroup);

// Chair - utilitarian, wooden
const chairGroup = new THREE.Group();
chairGroup.position.set(2, 0, 1);
chairGroup.rotation.y = -0.3;

// Seat
const seat = new THREE.Mesh(
  new THREE.BoxGeometry(1.2, 0.1, 1.2),
  woodMat
);
seat.position.y = 1;
chairGroup.add(seat);

// Legs
const legGeo = new THREE.CylinderGeometry(0.08, 0.06, 1, 8);
const positions = [[-0.5, 0.5], [0.5, 0.5], [-0.5, -0.5], [0.5, -0.5]];
positions.forEach(pos => {
  const leg = new THREE.Mesh(legGeo, woodMat);
  leg.position.set(pos[0], 0.5, pos[1]);
  chairGroup.add(leg);
});

// Backrest
const backrest = new THREE.Mesh(
  new THREE.BoxGeometry(1.2, 1.2, 0.1),
  woodMat
);
backrest.position.set(0, 1.6, -0.55);
chairGroup.add(backrest);

// Blue overalls draped over chair
const clothGroup = new THREE.Group();
const cloth1 = new THREE.Mesh(
  new THREE.PlaneGeometry(0.8, 1.5, 8, 8),
  clothMat
);
cloth1.position.set(0, 1.2, 0.2);
cloth1.rotation.x = -0.2;
cloth1.castShadow = true;

// Deform cloth slightly for draped look
const posAttribute = cloth1.geometry.attributes.position;
for (let i = 0; i < posAttribute.count; i++) {
  const x = posAttribute.getX(i);
  const y = posAttribute.getY(i);
  const z = posAttribute.getZ(i);
  posAttribute.setZ(i, z + Math.sin(x * 3) * 0.1 + Math.cos(y * 2) * 0.05);
}
cloth1.geometry.computeVertexNormals();

clothGroup.add(cloth1);

// Another piece hanging down
const cloth2 = new THREE.Mesh(
  new THREE.PlaneGeometry(0.6, 1.2, 6, 6),
  clothMat
);
cloth2.position.set(0.2, 0.6, 0.8);
cloth2.rotation.x = 0.4;
cloth2.castShadow = true;
clothGroup.add(cloth2);

chairGroup.add(clothGroup);
roomGroup.add(chairGroup);

// Threadbare rug
const rugGeo = new THREE.PlaneGeometry(4, 3, 32, 24);
const rugMat = new THREE.MeshStandardMaterial({ 
  color: 0x6b5b4f, 
  roughness: 1,
  side: THREE.DoubleSide
});

// Distort rug for threadbare look
const rugPos = rugGeo.attributes.position;
for (let i = 0; i < rugPos.count; i++) {
  const x = rugPos.getX(i);
  const y = rugPos.getY(i);
  const z = rugPos.getZ(i);
  // Uneven wear
  const wear = Math.sin(x * 2) * Math.cos(y * 2) * 0.05;
  rugPos.setZ(i, z + wear + (Math.random() - 0.5) * 0.02);
}
rugGeo.computeVertexNormals();

const rug = new THREE.Mesh(rugGeo, rugMat);
rug.rotation.x = -Math.PI / 2;
rug.position.set(-1, 0.02, -1);
rug.receiveShadow = true;
roomGroup.add(rug);

// Dust particles in the light beams
const particleCount = 400;
const particleGeo = new THREE.BufferGeometry();
const particlePos = new Float32Array(particleCount * 3);
const particleVel = [];

for (let i = 0; i < particleCount; i++) {
  // Concentrate near window light beam
  particlePos[i * 3] = -4 + Math.random() * 4; // x
  particlePos[i * 3 + 1] = Math.random() * 5; // y
  particlePos[i * 3 + 2] = -3 + Math.random() * 6; // z

  particleVel.push({
    x: (Math.random() - 0.5) * 0.005,
    y: (Math.random() - 0.5) * 0.005,
    z: (Math.random() - 0.5) * 0.005
  });
}

particleGeo.setAttribute('position', new THREE.BufferAttribute(particlePos, 3));
const particleMat = new THREE.PointsMaterial({
  color: 0xfff8e7,
  size: 0.03,
  transparent: true,
  opacity: 0.6,
  blending: THREE.AdditiveBlending
});
const dustParticles = new THREE.Points(particleGeo, particleMat);
scene.add(dustParticles);

// Volumetric light shaft (simulated with transparent cone)
const shaftGeo = new THREE.ConeGeometry(3, 8, 32, 1, true);
const shaftMat = new THREE.MeshBasicMaterial({
  color: 0xfff4e0,
  transparent: true,
  opacity: 0.03,
  side: THREE.DoubleSide,
  blending: THREE.AdditiveBlending,
  depthWrite: false
});
const lightShaft = new THREE.Mesh(shaftGeo, shaftMat);
lightShaft.position.set(-4, 4, 0);
lightShaft.rotation.z = -Math.PI / 4;
lightShaft.rotation.x = Math.PI / 8;
scene.add(lightShaft);

// Camera position - low angle, feeling of being watched
camera.position.set(4, 1.6, 4.5);
camera.lookAt(0, 2.5, -6);

// Animation state
let flickerTimer = 0;

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const delta = clock.getDelta();

  // Animate dust particles
  const positions = dustParticles.geometry.attributes.position.array;
  for (let i = 0; i < particleCount; i++) {
    positions[i * 3] += particleVel[i].x + Math.sin(t * 0.5 + i) * 0.002;
    positions[i * 3 + 1] += particleVel[i].y + Math.cos(t * 0.3 + i) * 0.001;
    positions[i * 3 + 2] += particleVel[i].z;

    // Reset if out of bounds
    if (positions[i * 3 + 1] > 5) positions[i * 3 + 1] = 0;
    if (positions[i * 3] > 0) positions[i * 3] = -4;
  }
  dustParticles.geometry.attributes.position.needsUpdate = true;

  // Telescreen flicker - irregular, oppressive
  flickerTimer += 0.05;
  if (Math.random() > 0.95) {
    telescreenLight.intensity = 0.5 + Math.random() * 0.6;
    tsScreenMat.color.setHSL(0.6, 0.4, 0.3 + Math.random() * 0.3);
  } else {
    telescreenLight.intensity = THREE.MathUtils.lerp(telescreenLight.intensity, 0.8, 0.1);
  }

  // Subtle light shaft movement (dust motes in air)
  lightShaft.rotation.z = -Math.PI / 4 + Math.sin(t * 0.2) * 0.05;

  // Very subtle camera drift - uneasy feeling
  camera.position.y = 1.6 + Math.sin(t * 0.1) * 0.02;

  renderer.render(scene, camera);
}

animate();

